{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/lab",
  "data": [
    {
      "name": "comment",
      "type": "CommentThreadData",
      "required": true,
      "description": "The thread: its first comment, carrying its replies, reactions, optional anchor, transient `typingUsers`, and per-comment `seenBy` metadata. `seenBy` is not rendered by default but remains available to comment render callbacks."
    },
    {
      "name": "isSelected",
      "type": "boolean",
      "description": "Whether the thread is open, controlled: body unclamped and replies shown. Omit it to let the thread own selection. Host-controlled selection never moves focus or opens the reply composer; a viewer Reply action does."
    },
    {
      "name": "onSelectedChange",
      "type": "(isSelected: boolean) => void",
      "description": "Called when the viewer opens or closes the thread."
    },
    {
      "name": "onDismiss",
      "type": "() => void",
      "description": "Hands the thread its anchored host’s light dismissal. A press outside the thread, or an Escape no layer inside it handled, calls it. While a reply or edit holds unsaved text, the first request instead shakes the thread, returns focus to the draft, and announces; the next consecutive request dismisses, and typing or pressing inside the thread re-arms the warning. Pair it with `hasLightDismiss={false}` and `hasEscapeDismiss={false}` on the host Popover. Omit it and the thread never dismisses anything."
    },
    {
      "name": "currentUser",
      "type": "CommentUser",
      "description": "The viewer, for own-comment actions and the reply avatar."
    },
    {
      "name": "mode",
      "type": "'interactive' | 'non-editable' | 'read-only'",
      "default": "'interactive'",
      "description": "Which actions show, as on Comments."
    },
    {
      "name": "container",
      "type": "'section' | 'card'",
      "default": "'section'",
      "description": "The parent surface: an outlined Card on a page, or a Section without outer rules inside a card or popover."
    },
    {
      "name": "onSubmit",
      "type": "(content: string, parentCommentId?: string) => void | Promise<void>",
      "description": "Posts a reply, always with the thread’s first comment as the parent. A rejected Promise restores the draft and shows an error with Retry."
    },
    {
      "name": "onComposerDraftChange",
      "type": "(value: string, context: CommentComposerContext) => void",
      "description": "Reports internally owned reply and edit drafts, including seeds and an empty value after submit, cancel, or a target switch. Route updates by `context` and own transport timing in your app."
    },
    {
      "name": "onSaveEdit",
      "type": "(commentId: string, content: string) => void | Promise<void>",
      "description": "Adds Edit to the viewer’s own comments and saves the new Markdown."
    },
    {
      "name": "onDelete",
      "type": "(commentId: string) => void | Promise<void>",
      "description": "Adds Delete to the viewer’s own comments, confirmed in a dialog first."
    },
    {
      "name": "onReact",
      "type": "(commentId: string, reactionKey: string, option?: CommentReactionOption) => void | Promise<void>",
      "description": "Toggles the viewer’s reaction by its stable key."
    },
    {
      "name": "onRetryComment",
      "type": "(commentId: string) => void | Promise<void>",
      "description": "Adds Retry to a comment whose `status` is `error`."
    },
    {
      "name": "onResolveThread",
      "type": "(commentId: string) => void | Promise<void>",
      "description": "Adds Mark as resolved to an open thread."
    },
    {
      "name": "onReopenThread",
      "type": "(commentId: string) => void | Promise<void>",
      "description": "Adds Reopen to a resolved thread."
    },
    {
      "name": "loadVersions",
      "type": "(commentId: string) => Promise<readonly CommentVersion[]>",
      "description": "Loads a comment’s edit history, newest first."
    },
    {
      "name": "onUploadImages",
      "type": "(files: readonly File[], context: CommentComposerContext) => CommentUploadedImage[] | Promise<CommentUploadedImage[]>",
      "description": "Uploads images attached, pasted, or dropped in the reply composer and appends them as Markdown images."
    },
    {
      "name": "isSubmitting",
      "type": "boolean",
      "default": "false",
      "description": "Host-controlled pending state for the reply composer."
    },
    {
      "name": "composerPlaceholder",
      "type": "string",
      "description": "Placeholder of the reply composer. Defaults to the localized \"Reply to <name>…\"."
    },
    {
      "name": "highlightColor",
      "type": "'blue' | 'cyan' | 'gray' | 'green' | 'orange' | 'pink' | 'purple' | 'red' | 'teal' | 'yellow'",
      "default": "'yellow'",
      "description": "The palette color your app highlights the thread’s passage in."
    },
    {
      "name": "reactionOptions",
      "type": "readonly CommentReactionOption[]",
      "default": "DEFAULT_COMMENT_REACTIONS",
      "description": "The reactions Add reaction offers."
    },
    {
      "name": "agentCommands",
      "type": "readonly CommentAgentCommand[]",
      "description": "Agents a reply can address with a `/` command."
    },
    {
      "name": "composerTriggers",
      "type": "readonly ChatComposerTrigger[]",
      "description": "Typeahead triggers for the reply composer, such as an `@` people search."
    },
    {
      "name": "markdownPlugins",
      "type": "readonly MarkdownPluginEntry[]",
      "description": "Block Markdown plugins for comment bodies."
    },
    {
      "name": "markdownInlinePlugins",
      "type": "readonly MarkdownInlinePlugin[]",
      "description": "Inline Markdown plugins for comment bodies, such as mentions."
    },
    {
      "name": "getReplyMention",
      "type": "(author: CommentUser) => string | undefined",
      "description": "Seeds a reply to a reply with a mention of its author."
    },
    {
      "name": "hasEmojiPicker",
      "type": "boolean",
      "default": "true",
      "description": "Whether the reply composer offers the emoji picker."
    },
    {
      "name": "renderAnchor",
      "type": "(comment: CommentThreadData, defaultAnchor: ReactNode) => ReactNode",
      "description": "Replaces the thread’s quoted passage."
    },
    {
      "name": "renderBody",
      "type": "(comment: CommentData) => ReactNode",
      "description": "Replaces a comment’s Markdown body."
    },
    {
      "name": "renderVersionBody",
      "type": "(version: CommentVersion) => ReactNode",
      "description": "Replaces the body of a version in the edit history."
    },
    {
      "name": "renderAdditionalActions",
      "type": "(comment: CommentData) => ReactNode",
      "description": "Adds product actions to a comment’s header."
    },
    {
      "name": "renderComposer",
      "type": "(props: CommentComposerRenderProps) => ReactNode",
      "description": "Replaces the reply composer’s input while the thread keeps its draft and state."
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
